const path = require('path');

const ROOT = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';

function collectFiles(dir, prefix) {
  const files = [];

  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;

    const relativePath = prefix ? `${prefix}/${entry.name}` : entry.name;

    if (entry.isDirectory()) {
      files.push(...collectFiles(path.join(dir, entry.name), relativePath));
      continue;
    }

    if (!entry.isFile()) continue;
    if (entry.name === MANIFEST_NAME) continue;

    files.push(relativePath);
  }

  return files;
}

const files = collectFiles(ROOT, '').sort();
const manifest = { files };

fs.writeFileSync(path.join(ROOT, MANIFEST_NAME), `${JSON.stringify(manifest, null, 2)}\n`);

console.log(JSON.stringify(manifest, null, 2));

